import Database from "better-sqlite3";

const dbPath = "/home/user/qwik-app/metadata.db";
const db = new Database(dbPath);

// Initialize the files table
db.exec(`
  CREATE TABLE IF NOT EXISTS files (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    size INTEGER NOT NULL,
    mime TEXT NOT NULL,
    tag TEXT NOT NULL
  )
`);

export default db;
export interface FileMetadata {
  id: number;
  name: string;
  size: number;
  mime: string;
  tag: string;
}

import { type RequestHandler } from "@builder.io/qwik-city";
import fs from "fs";
import path from "path";
import db from "../../../db";

export const onPost: RequestHandler = async (event) => {
  try {
    const formData = await event.request.formData();
    const file = formData.get("file");
    const tag = formData.get("tag");

    if (
      !file ||
      typeof file === "string" ||
      !file.name ||
      !tag ||
      typeof tag !== "string" ||
      tag.trim() === ""
    ) {
      return event.json(400, { error: "File or tag is missing or invalid" });
    }

    const uploadsDir = "/home/user/qwik-app/public/uploads";
    if (!fs.existsSync(uploadsDir)) {
      fs.mkdirSync(uploadsDir, { recursive: true });
    }

    const filePath = path.join(uploadsDir, file.name);
    const arrayBuffer = await file.arrayBuffer();
    const buffer = Buffer.from(arrayBuffer);
    await fs.promises.writeFile(filePath, buffer);

    // Insert metadata into SQLite
    const stmt = db.prepare(
      "INSERT INTO files (name, size, mime, tag) VALUES (?, ?, ?, ?)"
    );
    const result = stmt.run(
      file.name,
      file.size,
      file.type || "application/octet-stream",
      tag
    );

    const insertedId = Number(result.lastInsertRowid);

    return event.json(201, {
      id: insertedId,
      name: file.name,
      size: file.size,
      mime: file.type || "application/octet-stream",
      tag: tag,
    });
  } catch (error: any) {
    return event.json(400, {
      error: error.message || "An error occurred during upload",
    });
  }
};

import { type RequestHandler } from "@builder.io/qwik-city";
import db from "../../../db";

export const onGet: RequestHandler = async (event) => {
  try {
    const files = db.prepare("SELECT * FROM files").all();
    return event.json(200, files);
  } catch (error: any) {
    return event.json(500, {
      error: error.message || "An error occurred while listing files",
    });
  }
};

import { type RequestHandler } from "@builder.io/qwik-city";
import fs from "fs";
import path from "path";
import db from "../../../db";

export const onDelete: RequestHandler = async (event) => {
  try {
    const { id } = event.params;
    const fileId = parseInt(id, 10);
    if (isNaN(fileId)) {
      return event.json(400, { error: "Invalid file ID" });
    }

    // Fetch the file metadata first
    const file = db.prepare("SELECT * FROM files WHERE id = ?").get(fileId) as any;
    if (!file) {
      return event.json(404, { error: "File not found" });
    }

    // Delete the physical file from disk if it exists
    const uploadsDir = "/home/user/qwik-app/public/uploads";
    const filePath = path.join(uploadsDir, file.name);

    try {
      if (fs.existsSync(filePath)) {
        await fs.promises.unlink(filePath);
      }
    } catch (err) {
      // Ignore disk deletion error if file is missing
    }

    // Delete from database
    db.prepare("DELETE FROM files WHERE id = ?").run(fileId);

    return event.json(200, { success: true });
  } catch (error: any) {
    return event.json(500, {
      error: error.message || "An error occurred during deletion",
    });
  }
};

import { component$, useStore, useVisibleTask$, $ } from "@builder.io/qwik";
import { routeLoader$ } from "@builder.io/qwik-city";
import db from "../../db";

export interface FileItem {
  id: number;
  name: string;
  size: number;
  mime: string;
  tag: string;
}

export const useFilesLoader = routeLoader$(async () => {
  try {
    const files = db.prepare("SELECT * FROM files").all() as FileItem[];
    return files;
  } catch (err) {
    return [];
  }
});

export default component$(() => {
  const initialFiles = useFilesLoader();
  const state = useStore<{ files: FileItem[] }>({
    files: initialFiles.value || [],
  });

  // Keep state in sync or fetch on mount to make sure it's always up to date
  useVisibleTask$(async () => {
    try {
      const res = await fetch("/files/list");
      if (res.ok) {
        state.files = await res.json();
      }
    } catch (err) {
      console.error("Failed to load files", err);
    }
  });

  const handleUpload = $(async (e: SubmitEvent) => {
    e.preventDefault();
    const form = e.target as HTMLFormElement;
    const formData = new FormData(form);

    const fileInput = form.querySelector("#file-input") as HTMLInputElement;
    const tagInput = form.querySelector("#tag-input") as HTMLInputElement;

    if (!fileInput || !fileInput.files || fileInput.files.length === 0) {
      alert("Please select a file to upload.");
      return;
    }

    if (!tagInput || !tagInput.value.trim()) {
      alert("Please provide a tag.");
      return;
    }

    try {
      const res = await fetch("/files/upload", {
        method: "POST",
        body: formData,
      });

      if (res.status === 201) {
        const newFile = await res.json();
        state.files = [...state.files, newFile];
        form.reset();
      } else {
        const errData = await res.json();
        alert(`Upload failed: ${errData.error || "Unknown error"}`);
      }
    } catch (err) {
      alert("An error occurred during upload.");
    }
  });

  const handleDelete = $(async (id: number) => {
    try {
      const res = await fetch(`/files/${id}`, {
        method: "DELETE",
      });

      if (res.ok) {
        state.files = state.files.filter((f) => f.id !== id);
      } else {
        const errData = await res.json();
        alert(`Deletion failed: ${errData.error || "Unknown error"}`);
      }
    } catch (err) {
      alert("An error occurred during deletion.");
    }
  });

  return (
    <div style={{ padding: "20px", fontFamily: "sans-serif" }}>
      <h1>Server-Side File Explorer</h1>

      <div style={{ marginBottom: "30px" }}>
        <h2>Upload New File</h2>
        <form id="upload-form" onSubmit$={handleUpload}>
          <div style={{ marginBottom: "10px" }}>
            <label htmlFor="file-input" style={{ display: "block", fontWeight: "bold" }}>
              File:
            </label>
            <input
              id="file-input"
              name="file"
              type="file"
              required
              style={{ marginTop: "5px" }}
            />
          </div>

          <div style={{ marginBottom: "15px" }}>
            <label htmlFor="tag-input" style={{ display: "block", fontWeight: "bold" }}>
              Tag:
            </label>
            <input
              id="tag-input"
              name="tag"
              type="text"
              required
              placeholder="e.g., documents, images"
              style={{ marginTop: "5px", padding: "5px", width: "250px" }}
            />
          </div>

          <button type="submit" style={{ padding: "8px 15px", cursor: "pointer" }}>
            Upload File
          </button>
        </form>
      </div>

      <hr />

      <div>
        <h2>Uploaded Files</h2>
        <div id="file-list">
          {state.files.length === 0 ? (
            <p>No files uploaded yet.</p>
          ) : (
            <ul style={{ listStyleType: "none", padding: 0 }}>
              {state.files.map((file) => (
                <li
                  key={file.id}
                  style={{
                    border: "1px solid #ccc",
                    borderRadius: "4px",
                    padding: "10px",
                    marginBottom: "10px",
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center",
                  }}
                >
                  <div>
                    <strong>Name:</strong> {file.name} <br />
                    <strong>Size:</strong> {file.size} bytes <br />
                    <strong>MIME:</strong> {file.mime} <br />
                    <strong>Tag:</strong> {file.tag}
                  </div>
                  <button
                    class="delete-btn"
                    data-id={file.id}
                    onClick$={() => handleDelete(file.id)}
                    style={{
                      backgroundColor: "#ff4d4d",
                      color: "white",
                      border: "none",
                      padding: "8px 12px",
                      borderRadius: "4px",
                      cursor: "pointer",
                    }}
                  >
                    Delete
                  </button>
                </li>
              ))}
            </ul>
          )}
        </div>
      </div>
    </div>
  );
});

